    const key = [2]u64{ state.bucket1, state.bucket2 };
    if (visited.contains(key)) {
        return false;
    }

    try visited.put(key, {});
    try queue.append(state);
    return true;
}

fn gcd(a: u64, b: u64) u64 {
    var x = a;
    var y = b;
    while (y != 0) {
        const temp = y;
        y = x % y;
        x = temp;
    }
    return x;
}
